        public void Print(
            IWeaponGetter item,
            StructuredStringBuilder sb,
            string? name = null,
            Weapon.Mask<bool>? printMask = null)
        {
            if (name == null)
            {
                sb.AppendLine($"Weapon =>");
            }
            else
            {
                sb.AppendLine($"{name} (Weapon) =>");
            }
            using (sb.Brace())
            {
                ToStringFields(
                    item: item,
                    sb: sb,
                    printMask: printMask);
            }
        }
        
