        protected WeaponBinaryOverlay(
            MemoryPair memoryPair,
            BinaryOverlayFactoryPackage package)
            : base(
                memoryPair: memoryPair,
                package: package)
        {
            this.CustomCtor();
        }

        public static IWeaponGetter WeaponFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new WeaponBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static IWeaponGetter WeaponFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return WeaponFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.OBND:
                {
                    _ObjectBoundsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Weapon_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.FULL:
                {
                    _NameLocation = (stream.Position - offset);
                    return (int)Weapon_FieldIndex.Name;
                }
                case RecordTypeInts.MODL:
                case RecordTypeInts.MODT:
                case RecordTypeInts.MODS:
                case RecordTypeInts.MODB:
                case RecordTypeInts.MODD:
                {
                    if (!lastParsed.ParsedIndex.HasValue
                        || lastParsed.ParsedIndex.Value <= (int)Weapon_FieldIndex.Name)
                    {
                        this.Model = ModelBinaryOverlay.ModelFactory(
                            stream: stream,
                            package: _package,
                            translationParams: translationParams.DoNotShortCircuit());
                        return new ParseResult((int)Weapon_FieldIndex.Model, type);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)Weapon_FieldIndex.DropSound)
                    {
                        this.ShellCasingModel = ModelBinaryOverlay.ModelFactory(
                            stream: stream,
                            package: _package,
                            translationParams: Weapon_Registration.ShellCasingModelConverter.DoNotShortCircuit());
                        return new ParseResult((int)Weapon_FieldIndex.ShellCasingModel, type);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)Weapon_FieldIndex.ShellCasingModel)
                    {
                        this.ScopeModel = ModelBinaryOverlay.ModelFactory(
                            stream: stream,
                            package: _package,
                            translationParams: Weapon_Registration.ScopeModelConverter.DoNotShortCircuit());
                        return new ParseResult((int)Weapon_FieldIndex.ScopeModel, type);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)Weapon_FieldIndex.ScopeEffect)
                    {
                        this.WorldModel = ModelBinaryOverlay.ModelFactory(
                            stream: stream,
                            package: _package,
                            translationParams: Weapon_Registration.WorldModelConverter.DoNotShortCircuit());
                        return new ParseResult((int)Weapon_FieldIndex.WorldModel, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                this.Model = ModelBinaryOverlay.ModelFactory(
                                    stream: stream,
                                    package: _package,
                                    translationParams: translationParams.DoNotShortCircuit());
                                return new ParseResult((int)Weapon_FieldIndex.Model, type);
                            }
                            case 1:
                            {
                                this.ShellCasingModel = ModelBinaryOverlay.ModelFactory(
                                    stream: stream,
                                    package: _package,
                                    translationParams: Weapon_Registration.ShellCasingModelConverter.DoNotShortCircuit());
                                return new ParseResult((int)Weapon_FieldIndex.ShellCasingModel, type);
                            }
                            case 2:
                            {
                                this.ScopeModel = ModelBinaryOverlay.ModelFactory(
                                    stream: stream,
                                    package: _package,
                                    translationParams: Weapon_Registration.ScopeModelConverter.DoNotShortCircuit());
                                return new ParseResult((int)Weapon_FieldIndex.ScopeModel, type);
                            }
                            case 3:
                            {
                                this.WorldModel = ModelBinaryOverlay.ModelFactory(
                                    stream: stream,
                                    package: _package,
                                    translationParams: Weapon_Registration.WorldModelConverter.DoNotShortCircuit());
                                return new ParseResult((int)Weapon_FieldIndex.WorldModel, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.ICON:
                {
                    _LargeIconFilenameLocation = (stream.Position - offset);
                    return (int)Weapon_FieldIndex.LargeIconFilename;
                }
                case RecordTypeInts.MICO:
                {
                    _SmallIconFilenameLocation = (stream.Position - offset);
                    return (int)Weapon_FieldIndex.SmallIconFilename;
                }
                case RecordTypeInts.SCRI:
                {
                    _ScriptLocation = (stream.Position - offset);
                    return (int)Weapon_FieldIndex.Script;
                }
                case RecordTypeInts.EITM:
                {
                    _ObjectEffectLocation = (stream.Position - offset);
                    return (int)Weapon_FieldIndex.ObjectEffect;
                }
                case RecordTypeInts.EAMT:
                {
                    _EnchantmentChargeAmountLocation = (stream.Position - offset);
                    return (int)Weapon_FieldIndex.EnchantmentChargeAmount;
                }
                case RecordTypeInts.NAM0:
                {
                    _AmmoLocation = (stream.Position - offset);
                    return (int)Weapon_FieldIndex.Ammo;
                }
                case RecordTypeInts.DEST:
                case RecordTypeInts.DSTD:
                {
                    this.Destructible = DestructibleBinaryOverlay.DestructibleFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Weapon_FieldIndex.Destructible;
                }
                case RecordTypeInts.REPL:
                {
                    _RepairListLocation = (stream.Position - offset);
